try {
  let menu = "🍽️ *MENÚ DISPONIBLE*\n\n";

  const categorias = {};
  for (const item of $input.all()) {
    const stock = Number(item.json.stock);
    if (stock > 0) {
      const cat = item.json.categoria || "General";
      if (!categorias[cat]) categorias[cat] = [];
      categorias[cat].push(`• ${item.json.nombre} - $${item.json.precio}`);
    }
  }

  for (const cat in categorias) {
    menu += `*${cat}*\n`;
    menu += categorias[cat].join('\n') + "\n\n";
  }

  menu += "Presione 2 para realizar el pedido";

  return [{ json: { mensaje: menu } }];
} catch (error) {
