try {
  function normalizar(texto) {
    return (texto || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9 ]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }

  const encontrados = $('Validar Productos Existen').first().json.encontrados || [];

  let total = 0;
  let resumen = [];
  let agotados = [];

  for (const fila of $input.all()) {
    const nombreNorm = normalizar(fila.json.nombre);
    const precio = Number(fila.json.precio);
    const stock = Number(fila.json.stock);

    const pedidoMatch = encontrados.find(e => normalizar(e.nombreReal) === nombreNorm);

    if (pedidoMatch) {
      const cantidad = pedidoMatch.cantidad || 1;

      if (stock <= 0) {
        agotados.push(fila.json.nombre);
        continue;
      }

      const cantidadReal = Math.min(cantidad, stock); // no pedir más de lo que hay
      const subtotal = precio * cantidadReal;
      total += subtotal;
      resumen.push(`${cantidadReal}x ${fila.json.nombre} - $${subtotal.toLocaleString('es-CO')}`);
    }
  }

  return [{
    json: {
      agotados,
      carrito_temporal: resumen.join('\n'),
      precio_temporal: total,
      nombre_temporal: "",
      pantalla_actual: "esperando_confirmacion",
      telegram_id: $('Telegram Trigger').first().json.message.chat.id,
      ultimo_cambio: new Date().toLocaleString('es-CO')
    }
  }];
} catch (error) {
  const _tid = (() => { try { return $('Telegram Trigger').first().json.message.chat.id; } catch(e) { return 0; } })();
  return [{ json: { error: true, mensaje_error: '❌ Error en Calcular Total Y Carrito: ' + error.message, telegram_id: _tid } }];
}

