      .replace(/\s+/g, ' ')
      .trim();
  }

  const texto = $('Telegram Trigger').first().json.message.text;

  // Separar por coma, punto y coma, o salto de línea
  const partes = texto
    .split(/[,;\n]+/)
    .map(p => p.trim())
    .filter(p => p.length > 0);

  const productos = [];
  const cantidades = {};

  for (const parte of partes) {
    // Detectar cantidad al inicio: "2 cafe", "3x jugo", "dos empanada"
    const match = parte.match(/^(\d+)\s*x?\s*(.+)/i);
    if (match) {
      const qty = Math.min(parseInt(match[1]), 10); // máximo 10 por seguridad
      const prod = normalizar(match[2]);
      if (prod) {
        productos.push(prod);
        cantidades[prod] = qty;
      }
    } else {
      const prod = normalizar(parte);
      if (prod) {
        productos.push(prod);
        cantidades[prod] = cantidades[prod] || 1;
      }
    }
  }

  return [{ json: { productos, cantidades } }];
} catch (error) {
  const _tid = (() => { try { return $('Telegram Trigger').first().json.message.chat.id; } catch(e) { return 0; } })();
