try {
  const pedidos = $input.all();
  const hoy = new Date().toLocaleDateString('es-CO');

  const ayer = new Date();
  ayer.setDate(ayer.getDate() - 1);
  const ayerStr = ayer.toLocaleDateString('es-CO');

  const pedidosHoy = pedidos.filter(p => p.json.fecha === hoy && p.json.estado !== 'Cancelado');
  const pedidosAyer = pedidos.filter(p => p.json.fecha === ayerStr && p.json.estado !== 'Cancelado');

  const totalHoy = pedidosHoy.reduce((s, p) => s + Number(p.json.total_pago || 0), 0);
  const totalAyer = pedidosAyer.reduce((s, p) => s + Number(p.json.total_pago || 0), 0);
  const diferencia = totalHoy - totalAyer;
  const tendencia = diferencia >= 0 ? '📈' : '📉';

  // Producto más vendido hoy
  const conteo = {};
  for (const p of pedidosHoy) {
    const productos = (p.json.detalles_pedido || '').split('\n');
    for (const prod of productos) {
      const nombre = prod.replace(/^\d+x /, '').split(' - ')[0].trim();
      if (nombre) conteo[nombre] = (conteo[nombre] || 0) + 1;
    }
  }
  const estrella = Object.entries(conteo).sort((a, b) => b[1] - a[1])[0];
  const productoEstrella = estrella ? `${estrella[0]} (${estrella[1]} veces)` : 'Sin datos';

  // Hora pico
  const horas = {};
  for (const p of pedidosHoy) {
    const hora = (p.json.hora || '').split(':')[0] + ':00';
    if (hora !== ':00') horas[hora] = (horas[hora] || 0) + 1;
  }
  const horaPico = Object.entries(horas).sort((a, b) => b[1] - a[1])[0];
  const horaPicoStr = horaPico ? `${horaPico[0]} (${horaPico[1]} pedidos)` : 'Sin datos';

  const reporte = `📊 REPORTE DIARIO — ${hoy}

  📦 Pedidos hoy: ${pedidosHoy.length}
  📦 Pedidos ayer: ${pedidosAyer.length} ${tendencia}

  💰 Total vendido hoy: $${totalHoy.toLocaleString('es-CO')}
  💰 Total vendido ayer: $${totalAyer.toLocaleString('es-CO')}
  ${diferencia >= 0 ? '✅' : '⚠️'} Diferencia: ${diferencia >= 0 ? '+' : ''}$${diferencia.toLocaleString('es-CO')}

  ⭐ Producto estrella: ${productoEstrella}
  🕐 Hora pico: ${horaPicoStr}

  ━━━━━━━━━━━━━━
  📋 Pedidos cancelados hoy: ${pedidos.filter(p => p.json.fecha === hoy && p.json.estado === 'Cancelado').length}`;

  return [{ json: { reporte } }];
} catch (error) {
  const _tid = (() => { try { return $('Telegram Trigger').first().json.message.chat.id; } catch(e) { return 0; } })();
  return [{ json: { error: true, mensaje_error: '❌ Error en Generar Reporte Financiero: ' + error.message, telegram_id: _tid } }];
}

