  function normalizar(texto) {
    return (texto || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9 ]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }

  const detalle = $('Guardar Pedido').first().json.detalles_pedido || '';

  // Parsear "2x Café - $6000" → { Café: 2 }
  const cantidadesVendidas = {};
  for (const linea of detalle.split('\n')) {
    const m = linea.match(/^(\d+)x (.+?) -/);
    if (m) {
      cantidadesVendidas[normalizar(m[2])] = parseInt(m[1]);
    }
  }

  let resultado = [];

  for (const item of $input.all()) {
    const nombreNorm = normalizar(item.json.nombre);
    const cantidad = cantidadesVendidas[nombreNorm] || 0;

    if (cantidad > 0) {
      const nuevoStock = Math.max(0, Number(item.json.stock) - cantidad);
      resultado.push({
        json: {
          id_producto: item.json.id_producto,
          nombre: item.json.nombre,
          stock: nuevoStock
        }
      });
    }
  }

  return resultado.length > 0 ? resultado : [{ json: { sin_cambios: true } }];
} catch (error) {
  const _tid = (() => { try { return $('Telegram Trigger').first().json.message.chat.id; } catch(e) { return 0; } })();
  return [{ json: { error: true, mensaje_error: '❌ Error en Calcular Nuevo Stock: ' + error.message, telegram_id: _tid } }];
}

try {
  function normalizar(texto) {
    return (texto || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9 ]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }

  const productosPedido = $('Parsear Productos Texto').first().json.productos || [];
  const cantidades = $('Parsear Productos Texto').first().json.cantidades || {};

  const itemsMenu = $input.all().map(item => ({
    nombreOriginal: item.json.nombre,
    nombreNorm: normalizar(item.json.nombre)
  }));

  const noEncontrados = [];
  const encontrados = [];

  for (const prod of productosPedido) {
    // Búsqueda exacta primero
    let match = itemsMenu.find(m => m.nombreNorm === prod);

    // Si no, búsqueda parcial (el pedido contiene el nombre o viceversa)
    if (!match) {
      match = itemsMenu.find(m => 
        m.nombreNorm.includes(prod) || prod.includes(m.nombreNorm)
      );
    }

    if (match) {
      encontrados.push({ pedido: prod, nombreReal: match.nombreOriginal, cantidad: cantidades[prod] || 1 });
    } else {
      noEncontrados.push(prod);
    }
  }

  return [{
    json: {
      productosPedido,
