try {
  function normalizar(texto) {
    return (texto || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/[̀-ͯ]/g, '')
      .replace(/[^a-z0-9 ]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }

  const textoCompleto = $('Telegram Trigger').first().json.message.text || '';
  // Extrae lo que viene después de "buscar "
  const termino = normalizar(textoCompleto.replace(/^buscar\s*/i, '').trim());

  if (!termino) {
    return [{ json: { mensaje: '🔍 Escribe qué buscas. Ejemplo: buscar café' } }];
  }

  const resultados = $input.all().filter(item => {
    const nombre = normalizar(item.json.nombre);
    const desc = normalizar(item.json.descripcion);
    const cat = normalizar(item.json.categoria);
    return nombre.includes(termino) || desc.includes(termino) || cat.includes(termino);
  });

  if (resultados.length === 0) {
    return [{ json: { mensaje: `❌ No encontré productos con "${termino}".\n\nEscribe *1* para ver el menú completo.` } }];
  }

  let mensaje = `🔍 Resultados para "${termino}":\n\n`;
  for (const r of resultados) {
    const stock = Number(r.json.stock);
    const disponible = stock > 0 ? '✅' : '❌ Agotado';
    mensaje += `${disponible} *${r.json.nombre}*\n`;
    mensaje += `   💰 $${r.json.precio}`;
    if (r.json.descripcion) mensaje += ` — ${r.json.descripcion}`;
    mensaje += '\n\n';
  }
  mensaje += 'Escribe *2* para realizar un pedido.';

  return [{ json: { mensaje } }];
} catch (error) {
  const _tid = (() => { try { return $('Telegram Trigger').first().json.message.chat.id; } catch(e) { return 0; } })();
  return [{ json: { error: true, mensaje_error: '❌ Error en Filtrar Productos Búsqueda: ' + error.message, telegram_id: _tid } }];
}

