try {
  const ahora = new Date();

  // getHours() → número entero 0-23
  // getMinutes() → número entero 0-59
  // getDay() → 0=Domingo, 1=Lunes ... 5=Viernes, 6=Sábado
  const horaActual   = ahora.getHours();
  const minutoActual = ahora.getMinutes();
  const dia          = ahora.getDay();

  // Convertir todo a minutos desde medianoche para comparar fácil
  const minutosAhora  = horaActual * 60 + minutoActual;
  const minutosAbre   = 8  * 60;   // 480  = 08:00 AM
  const minutosCierra = 17 * 60;   // 1020 = 05:00 PM

  // Lunes(1) a Viernes(5)
  const esDiaLaboral = dia >= 1 && dia <= 5;

  // Dentro de horario: día laboral Y hora entre apertura y cierre
  const estaAbierto = esDiaLaboral
                      && minutosAhora >= minutosAbre
                      && minutosAhora < minutosCierra;

  // Datos para el log y para el mensaje personalizado
  const diasSemana = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
  const horaStr = `${String(horaActual).padStart(2,'0')}:${String(minutoActual).padStart(2,'0')}`;

  return [{ json: {
    estaAbierto,
    dia_nombre: diasSemana[dia],
    hora_actual: horaStr,
    telegram_id: $('Telegram Trigger').first().json.message.chat.id
  }}];
} catch (error) {
  const _tid = (() => { try { return $('Telegram Trigger').first().json.message.chat.id; } catch(e) { return 0; } })();
  return [{ json: { error: true, mensaje_error: '❌ Error en Validar Horario Atención: ' + error.message, telegram_id: _tid } }];
}
